CREATE TABLE public.tikitaki_likes (post_id uuid NOT NULL REFERENCES public.tikitaki_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(post_id,user_id));
GRANT SELECT, INSERT, DELETE ON public.tikitaki_likes TO authenticated;
GRANT ALL ON public.tikitaki_likes TO service_role;
ALTER TABLE public.tikitaki_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_read ON public.tikitaki_likes FOR SELECT TO authenticated USING (true);
CREATE POLICY likes_add ON public.tikitaki_likes FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY likes_remove ON public.tikitaki_likes FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.tikitaki_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.tikitaki_posts(id) ON DELETE CASCADE, user_id uuid NOT NULL, body text NOT NULL CHECK (char_length(btrim(body)) BETWEEN 1 AND 500), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.tikitaki_comments TO authenticated;
GRANT ALL ON public.tikitaki_comments TO service_role;
ALTER TABLE public.tikitaki_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_read ON public.tikitaki_comments FOR SELECT TO authenticated USING (true);
CREATE POLICY comments_add ON public.tikitaki_comments FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid());
CREATE POLICY comments_remove ON public.tikitaki_comments FOR DELETE TO authenticated USING (user_id=auth.uid());
CREATE INDEX tikitaki_comments_post_created ON public.tikitaki_comments(post_id,created_at);
CREATE TABLE public.tikitaki_follows (follower_id uuid NOT NULL, following_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(follower_id,following_id), CHECK (follower_id <> following_id));
GRANT SELECT, INSERT, DELETE ON public.tikitaki_follows TO authenticated;
GRANT ALL ON public.tikitaki_follows TO service_role;
ALTER TABLE public.tikitaki_follows ENABLE ROW LEVEL SECURITY;
CREATE POLICY follows_read ON public.tikitaki_follows FOR SELECT TO authenticated USING (true);
CREATE POLICY follows_add ON public.tikitaki_follows FOR INSERT TO authenticated WITH CHECK (follower_id=auth.uid());
CREATE POLICY follows_remove ON public.tikitaki_follows FOR DELETE TO authenticated USING (follower_id=auth.uid());